    document.querySelectorAll('[data-role]').forEach(button=>button.disabled=busy||!editable);
    const attackIncident=ownAttackIncident();const attackWait=cooldown(Math.max(timeValue(attackIncident?.attackCooldownUntil),timeValue(viewer.attackCooldownUntil),timeValue(viewer.commandGuard?.cooldownUntil),timeValue(viewer.commandGuard?.lockedUntil)));const targetCaptured=(state.snapshot.captures||[]).some(capture=>capture.attackerTeamId===viewer.teamId&&capture.defenderTeamId===$('attack-target').value);const attackDisabled=busy||!running||viewer.role!=='attack'||!$('attack-target').value||attackWait>0||targetCaptured||!state.entryMode.attack;
    $('attack-command').disabled=busy||!running;$('attack-command-form').querySelector('button').disabled=attackDisabled;setTextButton('attack-command-form',attackWait?`Aguarde ${attackWait}s`:busy?'Executando…':'Executar ↵');$('attack-target').disabled=busy||!running||viewer.role!=='attack';$('switch-target').disabled=busy||!running||viewer.role!=='attack';
    const reserve=teams.find(team=>team.id===viewer.teamId)?.defenseReserve;const now=Date.now()+state.serverOffset;const recharge=activity.rules?.defenseRechargeMs||8000;const recovered=reserve?.nextChargeAt&&now>=reserve.nextChargeAt?1+Math.floor((now-reserve.nextChargeAt)/recharge):0;const charges=reserve?Math.min(reserve.capacity,reserve.charges+recovered):0;const chargeWait=reserve?.nextChargeAt?cooldown(reserve.nextChargeAt+recovered*recharge):0;setText('defense-reserve',reserve?`Reserva do time: ${charges}/${reserve.capacity} defesas${charges<reserve.capacity?` · +1 em ${chargeWait}s`:''}. Compartilhada entre os defensores.`:'');
    const defenseIncident=(state.snapshot.incidents||[]).find(incident=>incident.id===$('defense-incident').value);const defenseWait=cooldown(Math.max(state.defenseCommand==='logs'?0:timeValue(defenseIncident?.defenseCooldownUntil),timeValue(viewer.commandGuard?.cooldownUntil),timeValue(viewer.commandGuard?.lockedUntil)));const needsIncident=state.defenseCommand!=='logs';const invalidIncident=needsIncident&&(!defenseIncident||defenseIncident.status!=='active'||defenseIncident.stage<1||defenseIncident.responded);const noCharge=needsIncident&&charges===0;const defenseDisabled=busy||!running||viewer.role!=='defense'||invalidIncident||defenseWait>0||noCharge||!state.entryMode.defense;
    $('defense-command').disabled=busy||!running;$('defense-command-form').querySelector('button').disabled=defenseDisabled;setTextButton('defense-command-form',defenseWait?`Aguarde ${defenseWait}s`:noCharge?`Recarga ${chargeWait}s`:busy?'Executando…':'Executar ↵');$('defense-incident').disabled=busy||!running||viewer.role!=='defense';
