    for(const kind of ['attack','defense'])setHtml(`${kind}-tools`,tools.filter(tool=>tool.kind===kind).map(tool=>`<button type="button" class="compact-tool" data-kind="${kind}" data-command="${tool.id}" title="${escape(tool.name)}"><code>${tool.id}</code></button>`).join(''));
